parameters.functionCode:
// Extract user message and conversation history
const userMessage = $json.message || $json.userMessage || '';
const conversationHistory = $json.history || [];
const sessionId = $json.sessionId || require('crypto').randomUUID();

// Get or initialize session state
let sessionState = $json.state || {
  repoRN: null,
  repoNative: null,
  monorepoUrl: null,
  platforms: [],
  strategy: { startStage: 1, endStage: 3 },
  reviewers: [],
  targetBranch: 'main',
  step: 0, // Current step in conversation
  complete: false
};

return {
  json: {
    userMessage,
    conversationHistory,
    sessionId,
    sessionState
  }
};

const llmResponse = $json.choices[0].message.content;
const sessionState = $('Parse User Message').item.json.sessionState;
const userMessage = $('Parse User Message').item.json.userMessage;

// Try to extract structured action from LLM response
let action = null;
let updatedState = { ...sessionState };

// Check if LLM wants to start migration
const actionMatch = llmResponse.match(/\{\s*"action"\s*:\s*"start_migration"[\s\S]*?\}/m);
if (actionMatch) {
  try {
    action = JSON.parse(actionMatch[0]);
    updatedState.complete = true;
  } catch (e) {
    // Failed to parse, continue conversation
  }
}

// Extract information from user message and update state
// Check for GitHub repo URLs
const githubUrlMatch = userMessage.match(/https:\/\/github\.com\/[\w-]+\/[\w-]+/g);
if (githubUrlMatch && githubUrlMatch.length > 0) {
  if (!updatedState.repoRN) {
    updatedState.repoRN = githubUrlMatch[0];
    updatedState.step = Math.max(updatedState.step, 1);
  } else if (!updatedState.monorepoUrl && githubUrlMatch.length > 1) {
    updatedState.monorepoUrl = githubUrlMatch[1];
    updatedState.step = Math.max(updatedState.step, 2);
  } else if (!updatedState.monorepoUrl) {
    updatedState.monorepoUrl = githubUrlMatch[0];
    updatedState.step = Math.max(updatedState.step, 2);
  }
}

// Check for platforms
const platformsMatch = userMessage.toLowerCase();
if (platformsMatch.includes('ios')) updatedState.platforms.push('ios');
if (platformsMatch.includes('android')) updatedState.platforms.push('android');
if (platformsMatch.includes('web')) updatedState.platforms.push('web');
if (updatedState.platforms.length > 0) {
  updatedState.platforms = [...new Set(updatedState.platforms)]; // Remove duplicates
  updatedState.step = Math.max(updatedState.step, 3);
}

// Check for stage numbers
const stageMatch = userMessage.match(/stage\s*(\d)/i) || userMessage.match(/\b([0-3])\b/);
if (stageMatch) {
  const stage = parseInt(stageMatch[1]);
  if (stage >= 0 && stage <= 3) {
    if (!updatedState.strategy.startStage) {
      updatedState.strategy.startStage = stage;
    } else {
      updatedState.strategy.endStage = stage;
    }
    updatedState.step = Math.max(updatedState.step, 4);
  }
}

// Check for GitHub username
const usernameMatch = userMessage.match(/@([\w-]+)/) || 
                      (userMessage.match(/\b([\w-]{3,39})\b/) && !userMessage.match(/https?:\/\//));
if (usernameMatch && updatedState.reviewers.length === 0) {
  updatedState.reviewers.push(usernameMatch[1]);
  updatedState.step = Math.max(updatedState.step, 5);
}

// Check if user confirmed (yes, confirm, start, go, etc.)
if (/\b(yes|confirm|start|go|proceed|looks good|correct)\b/i.test(userMessage) && updatedState.step >= 5) {
  action = {
    action: 'start_migration',
    config: {
      repoRN: updatedState.repoRN,
      repoNative: updatedState.repoNative,
      monorepoUrl: updatedState.monorepoUrl,
      platforms: updatedState.platforms,
      strategy: updatedState.strategy,
      reviewers: updatedState.reviewers,
      targetBranch: updatedState.targetBranch
    }
  };
  updatedState.complete = true;
}

return {
  json: {
    assistantMessage: llmResponse,
    action,
    sessionState: updatedState,
    sessionId: $('Parse User Message').item.json.sessionId
  }
};

