  "message": "✅ Migration started successfully!\n\nMigration ID: " + $json.migrationId + "\n\nYou can monitor progress and approve PRs on GitHub: https://github.com/" + $('Parse LLM Response & Update State').item.json.action.config.reviewers[0] + "/" + $('Parse LLM Response & Update State').item.json.action.config.monorepoUrl.split('/').pop(),
  "migrationId": $json.migrationId,
  "complete": true
